+:root {
+  color-scheme: light;
+  --ink: #172a37;
+  --muted: #526672;
+  --paper: #fbfaf6;
+  --white: #fff;
+  --line: #dce5e2;
+  --green: #176b59;
+  --green-dark: #104c43;
+  --lime: #d7ed9f;
+  --pale: #edf4ef;
+  --gold: #d99a43;
+  --shadow: 0 16px 40px rgb(23 42 55 / 8%);
+}
+
+* { box-sizing: border-box; }
+html { scroll-behavior: smooth; }
+body {
+  margin: 0;
+  background: var(--paper);
+  color: var(--ink);
+  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+  font-size: 1rem;
+  line-height: 1.65;
+  -webkit-font-smoothing: antialiased;
+}
+a { color: var(--green); text-underline-offset: .2em; }
+a:hover { color: var(--green-dark); }
+a:focus-visible { outline: 3px solid var(--gold); outline-offset: 4px; border-radius: 2px; }
+::selection { color: var(--ink); background: var(--lime); }
+
+.skip-link {
+  position: absolute;
+  z-index: 20;
+  top: .75rem;
+  left: .75rem;
+  padding: .65rem 1rem;
+  transform: translateY(-160%);
+  background: var(--white);
+  color: var(--ink);
+  border-radius: .35rem;
+  box-shadow: var(--shadow);
+}
+.skip-link:focus { transform: translateY(0); }
+.site-header { position: relative; z-index: 2; background: var(--paper); border-bottom: 1px solid rgb(23 42 55 / 8%); }
+.header-inner, .footer-inner {
+  width: min(1120px, calc(100% - 3rem));
+  margin-inline: auto;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 2rem;
+}
+.header-inner { min-height: 82px; }
+.brand { display: inline-flex; align-items: center; gap: .75rem; color: var(--ink); text-decoration: none; line-height: 1.2; }
+.brand-mark {
+  display: grid;
+  width: 42px;
+  height: 42px;
+  place-items: center;
+  color: var(--white);
+  background: var(--green);
+  border-radius: 13px 13px 13px 4px;
+  font-size: .85rem;
+  font-weight: 800;
+  letter-spacing: -.06em;
+}
+.brand-name { font-size: .92rem; font-weight: 800; letter-spacing: -.02em; }
+.brand-name span { display: block; color: var(--muted); font-size: .77rem; font-weight: 600; }
