+.page-hero p:last-child { margin-bottom: 0; color: #d5e4dc; font-size: 1.1rem; }
+.content-width { width: min(820px, calc(100% - 3rem)); margin-inline: auto; }
+.document { padding-block: 3.5rem 5rem; color: #293d48; }
+.document h2 { margin: 2.8rem 0 1rem; color: var(--ink); font-size: 1.65rem; letter-spacing: -.035em; line-height: 1.25; }
+.document h2:first-child { margin-top: 0; }
+.document p { margin-bottom: 1rem; }
