+.document li { padding-left: .25rem; margin-block: .55rem; }
+.document li::marker { color: var(--green); }
+.document li ul { margin-block: .35rem; }
+
+.organization-section { padding-block: 4.5rem 6rem; }
+.organization-section h2 { margin-bottom: 1.7rem; }
+.people-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
+.person-card { display: flex; align-items: center; gap: 1rem; padding: 1.25rem; background: var(--white); border: 1px solid var(--line); border-radius: 8px; box-shadow: var(--shadow); }
+.person-initials { display: grid; flex: 0 0 54px; width: 54px; height: 54px; place-items: center; color: var(--green-dark); background: var(--lime); border-radius: 50%; font-weight: 800; }
+.person-card h3 { margin: 0 0 .25rem; font-size: 1.05rem; }
+.person-card h3 a { text-decoration-thickness: 1px; }
+.person-card p { margin: 0; color: var(--muted); font-size: .9rem; }
+.organization-note { margin: 1.5rem 0 0; color: var(--muted); font-size: .92rem; }
+
+.contributions-content { padding-block: 2.5rem 5rem; }
+.call-intro { padding: 1.5rem 1.65rem; background: var(--pale); border-left: 4px solid var(--green); border-radius: 0 8px 8px 0; }
+.lead { margin: 0; color: var(--ink); font-size: 1.12rem; }
+.content-section { padding-top: 3.3rem; }
+.content-section h2 { margin-bottom: 1.1rem; font-size: clamp(1.8rem, 4vw, 2.4rem); letter-spacing: -.045em; line-height: 1.15; }
+.content-section > p:not(.eyebrow):not(.status-note) { color: var(--muted); }
+.interest-list { display: grid; gap: .65rem; margin: 1.5rem 0; padding: 0; list-style: none; }
+.interest-list li { display: flex; align-items: flex-start; gap: 1rem; padding: 1rem 1.1rem; background: var(--white); border: 1px solid var(--line); border-radius: 7px; }
+.list-icon { flex: 0 0 2rem; color: var(--green); font-size: .76rem; font-weight: 850; letter-spacing: .05em; }
+.note-box { margin-top: 1.3rem; padding: 1.1rem 1.25rem; color: var(--ink); background: #f5f0e5; border-radius: 7px; }
+.submission-section { border-top: 1px solid var(--line); margin-top: 3rem; }
