+.steps-list > li::before { content: counter(steps, decimal-leading-zero); display: grid; width: 2.7rem; height: 2.7rem; place-items: center; color: var(--green-dark); background: var(--lime); border-radius: 50%; font-size: .78rem; font-weight: 850; }
+.steps-list h3 { margin: .15rem 0 .3rem; font-size: 1.08rem; }
+.steps-list p { margin: 0; color: var(--muted); }
+.steps-list ul { margin: .55rem 0 0; padding-left: 1.2rem; color: var(--muted); }
+.steps-list li li { margin-block: .25rem; }
