from html.parser import HTMLParser
from pathlib import Path
import re

class Links(HTMLParser):
    def __init__(self):
        super().__init__(); self.hrefs=[]
    def handle_starttag(self, tag, attrs):
        if tag in {'a','link','script'}:
            attrs=dict(attrs)
            if 'href' in attrs: self.hrefs.append(attrs['href'])
            if 'src' in attrs: self.hrefs.append(attrs['src'])

for html in sorted(Path('.').glob('*.html')):
    parser=Links(); parser.feed(html.read_text())
    missing=[]
    for href in parser.hrefs:
        if href.startswith(('https://','http://','#','mailto:')): continue
        target=(html.parent / href.split('#')[0]).resolve()
        if href.split('#')[0] and not target.exists(): missing.append(href)
    print(f'{html}: '+('all local links resolve' if not missing else f'missing {missing}'))

try:
    from bs4 import BeautifulSoup
    html=BeautifulSoup(Path('manifiesto.html').read_text(), 'html.parser')
    article=html.select_one('article.document')
    actual=' '.join(article.stripped_strings)
    source=Path('manifiesto.md').read_text()
    expected=[]
    for line in source.splitlines():
        line=re.sub(r'^\s*#+\s*', '', line)
        line=re.sub(r'^\s*[*-]\s*', '', line)
        if line.strip(): expected.append(line.strip())
    expected=' '.join(expected)
    actual=re.sub(r'\s+', ' ', actual)
    expected=re.sub(r'\s+', ' ', expected)
    print('Manifest text matches source:', actual == expected)
    if actual != expected:
        import difflib
        print('\n'.join(difflib.unified_diff([expected], [actual], fromfile='source', tofile='html', n=1)))
except ImportError:
    print('BeautifulSoup unavailable; skipped literal-text comparison')
